// Only profile-photo keys generated by our backend may be served publicly.
const ownerIdPattern = /^[A-Za-z0-9_-]{1,128}$/;
const fileNamePattern = /^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}\.(?:jpg|png|webp)$/i;

export function isProfilePhotoPath(ownerId, fileName) {
    return ownerIdPattern.test(ownerId) && fileNamePattern.test(fileName);
}

export function profilePhotoKey(ownerId, fileName) {
    if (!isProfilePhotoPath(ownerId, fileName)) throw new Error("Invalid profile photo path");
    return `profile-photos/${ownerId}/${fileName}`;
}

export function profilePhotoUrl(baseUrl, ownerId, fileName) {
    profilePhotoKey(ownerId, fileName);
    const origin = new URL(baseUrl).origin;
    return `${origin}/api/uploads/profile-photos/${ownerId}/${fileName}`;
}

// An upload is visible only after its owner saves this exact URL to their profile.
export function isCurrentProfilePhoto(storedImage, baseUrl, ownerId, fileName) {
    if (!storedImage || !isProfilePhotoPath(ownerId, fileName)) return false;
    try {
        const expected = new URL(profilePhotoUrl(baseUrl, ownerId, fileName));
        const actual = new URL(storedImage);
        return actual.origin === expected.origin &&
            actual.pathname === expected.pathname &&
            !actual.search && !actual.hash;
    } catch {
        return false;
    }
}
